globalThis.__IT_TREND_EMBEDDED_DATA__ = {"updated_at":"2026-11-22 18:40:12 JST","total_count":50,"config":{"selected_genres":["ai","web","infra","mobile","biz"],"other_genre_min_ratio":0.25,"max_age_hours":72.0,"genres":{"ai":"AI・LLM・機械学習","web":"Web開発・言語","infra":"インフラ・クラウド・セキュリティ","mobile":"モバイル・ガジェット・個人開発","biz":"ITビジネス・キャリア・マネジメント","other":"総合・その他IT"}},"articles":[{"title":"Anthropicの数学者、「Claude」と共同で「リーマン予想」を証明したと主張　Leanコミュニティが「正しい」と認定","url":"https://www.itmedia.co.jp/news/article/2611/22/2000003388/","source":"Hatena","published_at":"2026-11-22 08:42","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claudeと数学者がリーマン予想を証明、Leanコミュニティが正当性を認定","summary":"Anthropicの数学者レベント・アルポーゲ氏が、AI「Claude」と共同で数学の未解決問題「リーマン予想」を証明したと発表。証明は証明支援系「Lean」で記述された1700万行の形式証明として公開され、LeanおよびMathlibの開発コミュニティが複数の検証を経て「証明は正しい」と共同声明を出した。\n\n今回の証明は、リーマン予想そのものに加え「一般化リーマン予想」もカバーしている。Leanによる機械的な検証により、論理的な誤りがないことが確認された。今後は数学者が内容を理解し、論文としてまとめる作業が続く。AIが数学の歴史的難問解決に貢献した画期的な事例として注目される。","importance":10},{"title":"回収対象のAnker製モバイルバッテリーで火災発生か　型番「A1257」の一部に使用中止を呼びかけ","url":"https://japan.cnet.com/article/35255262/","source":"Hatena","published_at":"2026-11-22 07:17","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"Anker製モバイルバッテリー「A1257」で火災発生、回収対象製品の使用中止を呼びかけ","summary":"アンカー・ジャパンが回収を進めているモバイルバッテリー「Anker Power Bank（10000mAh、22.5W）」の型番「A1257」において、東京都内で火災が発生した。原因は調査中だが、電池内部のショートの恐れがあるとして、消費者庁は対象製品の直ちに使用中止を呼びかけている。\n\n回収対象は計40万台以上にのぼり、回収率は約55％にとどまる。ユーザーは本体背面または側面のシリアル番号を確認し、アンカーの受付フォームで回収対象かどうかを判別する必要がある。安全に関わる重要な情報であり、該当製品を所有している場合は速やかな対応が求められる。","importance":9},{"title":"Orca Botsが良さそう、何ができるのか","url":"https://zenn.dev/kg_motors_mibot/articles/orca-bot-intro","source":"Zenn","published_at":"2026-11-22 00:14","genre":"web","genre_label":"Web開発・言語","headline":"AIエージェントを常設し業務を自動化するIDE拡張「Orca Bots」","summary":"AIエージェント時代に最適化されたIDE「Orca」に、役割と記憶を持つBotを常設できる「Orca Bots」が追加された。SlackやGitHubと連携し、不具合調査からPR作成までの一連の作業を自動化できる点が特徴である。\n\n単なるAI呼び出しではなく、Git worktreeを活用したコード修正の独立性や、人間への引き継ぎフローが統合されている点が強力。日常業務のワークフローにAIを組み込み、依頼から成果物確認までを一貫して管理できるため、開発の自動化をさらに加速させる可能性がある。","importance":9},{"title":"\"リーマン予想の証明\"の検証は現在どこまで進んでいるか｜加藤文元","url":"https://note.com/katobungen/n/n9c2bb939b9c7","source":"Hatena","published_at":"2026-11-21 22:55","genre":"other","genre_label":"総合・その他IT","headline":"AIと数学者が証明したリーマン予想：Leanによる検証の現在地","summary":"Anthropicの数学者Levent Alpöge氏がClaudeを用いてリーマン予想を証明したという発表を受け、その検証状況をまとめた記事です。Leanという証明支援系で書かれた膨大なコードに対し、第三者による検証が驚異的なスピードで進んでいます。\n\n複数の独立したカーネルによる再検査が完了し、証明の文法的な正しさと命題の整合性が確認されつつあります。数学界の歴史的難問がAIの支援によって解かれた可能性が高まっており、証明支援系を用いた検証の重要性が改めて浮き彫りになっています。","importance":10},{"title":"情報漏えいを公表しないリスクの要点整理 - Qiita","url":"https://qiita.com/Maruo110/items/385b2c7ef5fbd074e6e2","source":"Hatena","published_at":"2026-11-22 07:25","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"情報漏えいを公表しないリスク：二重恐喝時代の新たなセキュリティ対策","summary":"情報漏えい発生時に「当局には報告するが世間には公表しない」という判断が、攻撃者の手口の変化によりリスクを増大させている。ランサムウェア集団によるリークサイトでのデータ公開が常態化する中、隠蔽が発覚した際の社会的信用失墜は、漏えいそのものよりも深刻なダメージとなる。\n\n企業は、漏えい発生時に備えて公表基準をCSIRTだけでなく広報・法務・経営層を含めて事前に合意しておく必要がある。攻撃者に公開のタイミングを委ねるのではなく、自らコントロール可能な形で対応を準備することが、現代のセキュリティガバナンスにおいて不可欠である。","importance":8},{"title":"作れるエンジニアから、価値を届けるエンジニアへ","url":"https://zenn.dev/kubell/articles/3c3490a3592bb1","source":"Zenn","published_at":"2026-11-21 00:50","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"AI時代にエンジニアが「作る」から「価値を届ける」へ役割を広げる方法","summary":"AIの普及により実装コストが低下した今、エンジニアには「速く作る」だけでなく「何を作るか」という意思決定への関与が求められています。本記事では、価値を「誰に」「何を」「どう届けるか」の3要素に分解し、エンジニアがプロダクトの意思決定に踏み込むための考え方を解説しています。\n\nターゲットの選定、ペインの深掘り、そしてユーザー体験の設計というプロセスをエンジニアが担うことで、プロダクトの価値を最大化できます。実装力という強みを活かしつつ、ビジネス領域へ役割を広げるための実践的な指針が示されています。","importance":7},{"title":"リーマン予想の証明、Lean開発者らが「正しい」と声明　Claudeを使って発見","url":"https://japan.cnet.com/article/35255270/","source":"Hatena","published_at":"2026-11-22 07:21","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"リーマン予想証明の正当性をLeanコミュニティが確認、AI活用による数学的ブレイクスルー","summary":"生成AI「Claude」を活用して数学の難問「リーマン予想」を証明した研究成果について、LeanおよびMathlibの開発コミュニティが正当性を認定する共同声明を発表した。1700万行に及ぶコードを複数の検証ツールで解析し、リーマン予想の命題と一致することを確認した。\n\nこの成果は、AIが複雑な数学的証明の構築を支援し、形式検証ツールがその正しさを保証するという、新しい数学研究のスタイルを示唆している。クレイ数学研究所の懸賞金審査とは別の手続きとなるが、コンピューターによる証明の検証としては極めて高い信頼性が示された。数学界におけるAI活用の歴史的転換点となる可能性がある。","importance":10},{"title":"「AIが私を追い越した」　リーマン予想「証明」の数学者自身も驚き：朝日新聞","url":"https://www.asahi.com/articles/ASVCP2WB0VCPDIFI008M.html","source":"Hatena","published_at":"2026-11-21 19:01","genre":"other","genre_label":"総合・その他IT","headline":"AIが167年来の難問「リーマン予想」を証明、数学界に衝撃","summary":"米国の数学者がAIの力を借りて、素数の分布に関する難問「リーマン予想」を証明したと発表し、数学界に大きな衝撃を与えています。リーマン予想は1859年に提唱されて以来、多くの数学者が挑んできた難問です。\n\n今回の証明は、AIが単なる計算ツールを超え、数学的推論のパートナーとして機能したことを示唆しています。証明の正当性については現在世界中で検証が進められており、AIが科学的発見を加速させる時代の到来を象徴する出来事として注目されています。","importance":10},{"title":"月3,000回の無料枠で、「AIに任せないこと」を先に決めた。猫耳秘書と宇宙を旅した話","url":"https://zenn.dev/nanako1129/articles/799de43c4e556c","source":"Zenn","published_at":"2026-11-22 00:00","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"無料枠でAIをゲームに導入する際の「任せないこと」の線引き","summary":"個人開発のブラウザゲームにAI秘書機能を導入する際、APIの無料枠制限を考慮し「AIに任せないこと」を明確に定義した事例。ゲームの核となるデータ精度を損なわず、AIがなくても成立する設計を徹底した。\n\nAIの回答をゲームの進行に直接介入させず、あくまで相談役として配置。環境変数でAI機能をオンオフできる仕組みを構築し、無料枠をテストで浪費しない工夫も施した。AIを「あれば便利」な補助機能として扱うことで、コストと体験のバランスを最適化する実践的なアプローチである。","importance":7},{"title":"Next.jsのストリーミングはLambda Web Functionsで動くか","url":"https://zenn.dev/ryota_09/articles/nextjs-suspense-streaming-lambda-web-functions","source":"Zenn","published_at":"2026-11-22 11:30","genre":"web","genre_label":"Web開発・言語","headline":"Lambda Web FunctionsでNext.jsのストリーミングは動くか？実測結果を公開","summary":"AWS Lambdaの新しい実行形態「Lambda Web Functions」上で、Next.jsのSuspenseストリーミングが段階表示されるかを検証。結論として、追加設定なしでVercelと同等のストリーミング挙動が確認された。以前のLambda Web Adapterでは実現できなかった段階表示が、Web Functionsでは標準でサポートされている。\n\n計測では、CloudFront経由のアクセスやコールドスタート時の挙動を含め、複数のアプリでチャンクの到着時刻を比較。Vercelとの違いはコールドスタート時のみであり、実用上のパフォーマンスは非常に高い。Next.jsをLambdaで動かす際の有力な選択肢となることが証明された。","importance":7},{"title":"Apache Iceberg v4の仕様を読んで、何が変わるのか考えてみた","url":"https://zenn.dev/penginpenguin/articles/5a04e281b16a68","source":"Zenn","published_at":"2026-11-21 23:33","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Apache Iceberg v4仕様が目指すメタデータ管理の効率化","summary":"Apache Iceberg v4の提案仕様では、manifest listの廃止とroot manifestへの統合、削除情報管理の最適化が議論されている。これは機能追加よりも、頻繁なコミットに伴うメタデータ増大という運用負荷の軽減を主目的としている。\n\n特にroot manifestがデータファイルを直接保持する構造への変更は、ストリーミング処理における書き込み負担を大幅に減らす可能性がある。また、equality deleteの新規書き込み廃止など、現場への影響が大きい変更も含まれており、データレイクの運用設計に大きな転換を迫るものとなる。","importance":8},{"title":"クロネコヤマトのロゴが外国人たちに人気らしい「これまでで一番好きな企業ロゴ」「これの絵柄が前後に入ったシャツを持ってるよ！」","url":"https://togetter.com/li/2773549","source":"Hatena","published_at":"2026-11-22 11:49","genre":"other","genre_label":"総合・その他IT","headline":"クロネコヤマトのロゴが海外で人気、日本独自の高品質な配送サービスが評価される","summary":"ヤマト運輸のクロネコロゴが、海外のSNSユーザーから「これまでで一番好きな企業ロゴ」として高い評価を受けている。単なるデザインの可愛らしさだけでなく、日本国内の旅行中に荷物をホテル間配送する「宅急便」の利便性や、決済サービス「NyanPay」のユニークな音など、日本独自のサービス体験が海外の人々に驚きと喜びを与えている。\n\n海外のユーザーからは、日本旅行時の体験談や、ロゴをプリントした特注パーカーを作るほどの熱狂ぶりが報告されている。日本の物流サービスが持つ「おもてなし」の精神や細やかな配慮が、ロゴというアイコンを通じて世界にポジティブな印象を与えている好例である。","importance":3},{"title":"新宿駅で財布を忘れて家に帰れない女の子から「PayPay1000円分を現金で交換して貰えませんか？」とお願いされ、「返さなくていいよ」と1000円あげたら喜ばれず戸惑っていた","url":"https://togetter.com/li/2773268","source":"Hatena","published_at":"2026-11-21 21:31","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"PayPay現金交換を装う詐欺手口と防犯意識の重要性","summary":"駅で「財布を忘れた」と困窮を装い、PayPay残高と現金の交換を求める詐欺手口が話題に。情報を抜き取る目的や、金銭を騙し取る目的が疑われており、知らない人との金銭やり取りは避けるべきとの注意喚起がなされている。\n\n警察が交通費を貸してくれる制度は自治体や状況により異なり、現在は貸し出しを行わないケースも多い。トラブルに巻き込まれないためには、安易に応じず交番へ案内するなどの冷静な対応が求められる。SNS上の情報拡散と、それに対する防犯意識の向上が重要である。","importance":5},{"title":"Lean verification of the Riemann Hypothesis","url":"https://leanprover-community.github.io/blog/posts/riemann-hypothesis/","source":"Hatena","published_at":"2026-11-22 01:27","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"リーマン予想のLean形式証明：コミュニティによる正当性確認の公式声明","summary":"Levent Alpöge氏によるリーマン予想の証明に対し、LeanおよびMathlibコミュニティがその正当性を認定する共同声明を発表。1700万行のコードがMathlibに依存し、エラーなくコンパイルされること、および独立した複数の検証ツールによって証明が正しいことが確認された。\n\n声明では、証明がリーマン予想の命題と正確に一致していることや、Leanの論理的欠陥を突くような不正がないことが強調されている。数学界における最も重要な未解決問題が、AIと形式検証技術の組み合わせによって解決されたことを示す歴史的な文書である。","importance":10},{"title":"Androidの野良アプリ導入が2027年1月から世界規模で制限へ　Googleの開発者認証が本格展開","url":"https://sumahodigest.com/?p=76937","source":"Hatena","published_at":"2026-11-20 09:20","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"Androidの野良アプリ導入制限へ：2027年1月から世界規模で認証制度を拡大","summary":"Googleは、Androidアプリ開発者への本人確認義務付けと、未認証アプリのサイドローディング制限を2027年1月から世界規模で展開すると発表しました。この変更はGoogle Playだけでなく、メーカー独自のアプリストアにも適用されます。\n\n未認証アプリのインストール自体は可能ですが、開発者オプションでの設定変更や24時間の待機時間が必要となるなど、手続きが大幅に複雑化します。セキュリティ強化を目的としていますが、自由なアプリ導入環境が大きく変わる転換点となります。","importance":9},{"title":"一番無難じゃないキャラが優勝　Suica「B案」とAI時代の愛されかた","url":"https://www.watch.impress.co.jp/docs/topic/watchplus/2157644.html","source":"Hatena","published_at":"2026-11-21 11:31","genre":"other","genre_label":"総合・その他IT","headline":"Suica新キャラ「B案」選出に見るAI時代の愛され方","summary":"Suicaの次期キャラクターに、奇抜なデザインの「B案（紫のうさぎ）」が選出された背景を解説。SNSでのファンアートの盛り上がりや、二次創作の余地を残す「余白」の重要性が、投票結果に大きく影響したと分析しています。\n\nまた、AIが何でも答えてくれる時代において、キャラクターやサービスが「話しかけたくなる鏡」として愛されることの重要性を指摘。Suicaが単なる決済デバイスから、心の拠り所となる存在へ進化する可能性について考察しています。","importance":4},{"title":"無料でセルフホストできWindows・macOS・LinuxアプリもあるRSSリーダー「WyrmRSS」、YouTube動画の再生やDiscord・Slackへの新着通知も可能","url":"https://gigazine.net/news/20261121-wyrmrss/","source":"Hatena","published_at":"2026-11-21 23:01","genre":"web","genre_label":"Web開発・言語","headline":"YouTube再生や通知機能も備えたオープンソースRSSリーダー「WyrmRSS」","summary":"「WyrmRSS」は、セルフホストおよびデスクトップアプリとして利用可能な無料のオープンソースRSSリーダー。RSS/Atomフィードの購読に加え、YouTube動画のアプリ内再生や、Discord/SlackへのWebhook通知機能を備える。\n\nフィードごとの表示モード設定や、タイトル・URLに基づく強力なフィルター機能を搭載しており、情報収集の効率化に寄与する。特にYouTubeのShorts除外や特定のキーワード抽出など、情報の取捨選択を細かく制御できる点が評価されており、個人開発のツールとして高い実用性を持つ。","importance":6},{"title":"相次ぐシステム障害、AIはどこまで関係しているのか--「12月はさらに深刻に」と専門家","url":"https://japan.cnet.com/article/35255244/","source":"Hatena","published_at":"2026-11-21 08:39","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"AIによる脆弱性発見の民主化と相次ぐシステム障害の背景","summary":"相次ぐシステム障害の背景に、AIによる脆弱性発見の効率化と攻撃の民主化があることを指摘。AIエージェントが短時間でコードを解析し、人間が見逃していた欠陥を大量に発見する「vulnpocalypse」の現状を解説しています。\n\n防御側もAIを活用しているものの、脆弱性が悪用されるまでの猶予時間が極端に短縮されており、管理者の対応が追いつかない状況が続いています。AIが生成したコードの品質問題と併せ、インターネットの基盤が以前より危うくなっている現状を専門家の視点から警鐘を鳴らしています。","importance":9},{"title":"KARTEを選んだのは顧客の私じゃない｜しがないサラリーマン","url":"https://note.com/kochan34123412/n/nf37511e42de9","source":"Hatena","published_at":"2026-11-21 07:36","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"KARTE情報漏えいから考える企業の情報連携と選定責任","summary":"KARTEの情報漏えい事故をめぐり、利用企業の発表文を比較し、企業の情報管理に対する姿勢を考察。外部サービスに情報を連携する際、その範囲や目的を顧客に対して明確に説明する責任が企業にあると説いています。\n\n事故発生時に「外部サービスのせい」にするのではなく、自社でどのようなデータを連携し、なぜそのサービスを選んだのかを振り返り、顧客に説明することの重要性を強調。企業がサービスを選定した後の管理責任と、透明性のあるコミュニケーションのあり方を問いかけています。","importance":6},{"title":"[AI-Driven Modernization] 既存コードからAIエージェント向けの仕様書を起こす「Reverse Spec Flow」を公開しました | Amazon Web Services","url":"https://aws.amazon.com/jp/blogs/news/aidm-introducing-reverse-spec-flow/","source":"Hatena","published_at":"2026-11-21 21:08","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"既存コードからAI向け仕様書を生成する「Reverse Spec Flow」","summary":"AWSが公開した「Reverse Spec Flow（RSF）」は、ブラックボックス化した既存コードから、AIエージェントが再構築に利用可能な「検証済みの仕様書」を生成するワークフロー。AIのハルシネーションを防ぐため、5つのフェーズと人による確認ゲートを設けている。\n\n仕様書の各記述にはコード上の根拠（path:line）を付与し、別のAIが検証を行うことで正確性を担保。コードから読み取れる事実と、技術に依存しない本質的な業務ルールを分離して記述する。AIの賢さに依存せず、手続きによって品質を制御するAI-Driven Modernizationの重要なツールである。","importance":9},{"title":"朝7時半、Claude Codeからの電話で起こされた","url":"https://zenn.dev/chobitnet/articles/mikoto-voice-call","source":"Zenn","published_at":"2026-11-22 08:55","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"Claude Codeと音声通話で連携、AIエージェントが電話をかけてくる仕組み","summary":"AIエージェント「みこと」とiPhoneで音声通話を実現し、作業完了や予定通知を電話で受け取れるシステムを構築。音声認識にはWhisper、音声合成と会話処理は自宅のMac Studioで行い、iOSのCallKitを活用してOS標準の着信画面を表示させる仕組みを解説する。\n\n単なるチャットではなく、音声での自然な対話と、必要に応じたClaude Codeによるバックグラウンドでの調査・作業実行を組み合わせることで、AIとのインタラクションを高度化している。Whisperの誤認識対策や、VoIP通知の制約など、実運用における技術的な工夫と苦労が記録されている。","importance":6},{"title":"[Rust] clap で引数か標準入力のどちらかでファイルを受け取る","url":"https://zenn.dev/00_4/articles/rust-clap-file-input","source":"Zenn","published_at":"2026-11-21 19:30","genre":"web","genre_label":"Web開発・言語","headline":"Rustのclapクレートで引数と標準入力を柔軟に受け取る実装手法","summary":"CLIツール開発において、ファイルパスを引数で受け取るか、標準入力から読み込むかの両方に対応させる実装方法を解説。clapクレートを使用し、Option<PathBuf>を活用して引数の有無を判定し、標準入力（stdin）とファイル入力を切り替える手法を紹介しています。\n\nまた、POSIXの慣習に従い「-」を標準入力として扱う実装や、引数なしの場合のハングアップを防ぐための考慮点についても言及。依存関係を増やさず、シンプルかつ使い勝手の良いCLIツールを構築するための実践的なテクニックがまとめられています。","importance":6},{"title":"はじめてのMCP接続をAgent Toolkit for AWSでやってみた(Windows&Claude Code)","url":"https://zenn.dev/yoss_k3/articles/486f8049b5d043","source":"Zenn","published_at":"2026-11-22 12:00","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Agent Toolkit for AWSとMCPを活用したAIエージェントのAWS運用効率化","summary":"AWS公式の「Agent Toolkit for AWS」とMCP（Model Context Protocol）を組み合わせ、AIコーディングエージェントにAWS環境を安全かつ効率的に操作させる手法を解説。Windows環境でのセットアップから、エージェントへのルール追加、CloudTrailによる操作ログの確認までを網羅している。\n\nMCPサーバーを導入することで、エージェントはドキュメント検索やスキル実行を直接行えるようになる。ルールを適切に設定することで、Web検索に頼っていた仕様確認が公式ドキュメント検索に切り替わり、より精度の高い回答が得られるようになる。インフラ構築や運用をAIに支援させるための実践的なガイドである。","importance":7},{"title":"GitHub - mitaku/andon: A one-person software factory: AI coding agents take tasks from a ledger through review to merge, and call the human only for decisions only they can make.","url":"https://github.com/mitaku/andon","source":"Hatena","published_at":"2026-11-21 19:52","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIエージェントによる自動化を追求する「Andon」","summary":"「Andon」は、AIエージェントが課題の実装からレビュー、マージまでを自律的に行う一人用ソフトウェア工場を実現するフレームワーク。人間は「何を作るか」など、自分にしかできない決断の時のみ介入する。\n\nトヨタ生産方式の「アンドン」に由来し、信頼境界ごとにコンテナ（セル）を配置。調整役のAIが課題を管理し、モデルの異なるレビュー役AIがPRをチェックする。機械が判断できることは自動化し、判断が必要な部分のみ人間に通知する「選択的ダークファクトリー」の設計思想に基づいている。","importance":9},{"title":"令和8年に「INFOBAR」が復活するも、通話とSMSしかできない「ダムフォン」に","url":"https://www.itmedia.co.jp/mobile/articles/2611/21/news011.html","source":"Hatena","published_at":"2026-11-21 15:49","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"通話とSMSに特化したダムフォン「INFOBAR ZERO」の狙い","summary":"KDDIが発表した、通話とSMSのみに対応する携帯電話「INFOBAR ZERO」の紹介。デジタルデトックスを背景に、SNSやWebブラウジングを排除し、人とつながる本来の価値にフォーカスした端末です。\n\nSIMロックフリーでオープンマーケット向けに販売され、スマホとの2台持ちを想定。収益性よりもブランディングや新しいライフスタイルの提案を重視しており、現代のデジタル社会において、あえて機能を絞り込んだ端末がどのような需要を掘り起こすのかが注目されています。","importance":5},{"title":"堅牢な受け入れテストを書くには？","url":"https://zenn.dev/yasuakiomokawa/articles/3ac970c3a3a1c7","source":"Zenn","published_at":"2026-11-21 18:09","genre":"web","genre_label":"Web開発・言語","headline":"AIエージェントに堅牢な受け入れテストを書かせるための4つの手順","summary":"AIコーディングエージェントが生成するテストが実装変更で壊れやすい問題を解決するため、堅牢なテストを書かせるための4つの手順を解説。受け入れ基準を外から見える振る舞いに限定し、コードの書き方の決まりは型やlintに任せることで、テストの保守性を高める手法を提案しています。\n\nさらに、テストを既存のテスト規則に倣わせることや、実装前にテストが失敗することを確認する重要性を強調。エージェントの都合ではなく、受け入れ基準の書き方を見直すことで、テストの書き換えを減らし、バグを見抜く力を維持するための実践的なガイドラインを提供しています。","importance":7},{"title":"おうちk8sでグローバルIP","url":"https://zenn.dev/neody/articles/915d907febbeca","source":"Zenn","published_at":"2026-11-21 22:24","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"VPSとWireGuardを用いたおうちk8sへのグローバルIP割り当て","summary":"AS運用をしていない環境でも、VPSの追加IP機能とWireGuard、BGP（FRRouting）を組み合わせることで、KubernetesのService LoadBalancerにグローバルIPを割り当てる手法を解説。\n\nVPS側でBGPを張り、WireGuardでトンネルを構築することで、自宅のk8sクラスターへ外部からアクセス可能なIPをルーティングする。MetalLBとVRFを組み合わせた高度なネットワーク構成により、自宅環境にいながらVPS事業者のIPアドレスを有効活用できる。ネットワークの柔軟性を高めるための興味深い検証事例である。","importance":7},{"title":"【TLA+】AIにテストケースを書かせるな。ルールを書け","url":"https://zenn.dev/karamage/articles/73027ee36796dc","source":"Hatena","published_at":"2026-11-22 12:08","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AI時代におけるテストのあり方：テストケースではなく「守るべきルール」を定義せよ","summary":"AIが実装とテストの両方を生成する現代において、人間がテストケースを考える手法は「自作自演の満点」を生み出し、バグを見逃すリスクがある。テストオラクル問題を踏まえ、著者は「テストケース」を書くのではなく、システムが絶対に守るべき「ルール」を定義し、形式検証ツール（TLA+やQuint）を用いて機械的に検証するアプローチを提唱する。\n\nチケット販売システムを例に、状態遷移と不変条件（インバリアント）を記述することで、網羅的な検証が可能になる。AIには問題作成を任せ、人間は「宇宙が崩壊するような物理法則」に匹敵するルールを定義する役割に徹することが、信頼性の高いソフトウェア開発の鍵となる。","importance":8},{"title":"日本でも「ダムフォン」は広がるか？　KDDIが「INFOBAR ZERO」で目指す2台持ちの新しい形","url":"https://www.itmedia.co.jp/mobile/articles/2611/21/news010.html","source":"Hatena","published_at":"2026-11-21 06:20","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"KDDIがINFOBAR ZEROで目指すデジタルデトックスの形","summary":"KDDIが発売する「INFOBAR ZERO」の企画意図と、ダムフォン市場の潮流を解説。スマホ依存やSNS疲れに対する「デジタルデトックス」の手段として、あえて機能を絞り込んだ端末を提案しています。\n\nセンドナンバー対応など、スマホとの2台持ちを前提とした設計になっており、通信料収入よりもブランディングを優先した戦略です。デジタル化が進む社会において、あえて「少ないデジタル」を選ぶという新しいライフスタイルを提示し、市場に一石を投じる試みとして注目されています。","importance":5},{"title":"設計書のないClassic ASP アプリを ASP.NET Core にマイグレーションしたときにやったこと","url":"https://zenn.dev/pomio/articles/classic-asp-migration-no-design-docs","source":"Zenn","published_at":"2026-11-21 17:56","genre":"web","genre_label":"Web開発・言語","headline":"設計書なしのClassic ASPアプリをASP.NET Coreへ移行する戦略","summary":"設計書が存在しない約10万ステップのClassic ASPシステムを、5人体制で1年かけてASP.NET Coreへマイグレーションした事例。納期優先のため「無理に最新技術を使わない」「キレイに作ろうとしない」という方針を立て、生成AIを活用したコード変換と、保守性を考慮したDapperの採用など、現実的な選択を行いました。\n\nアーキテクチャ選定では、難易度の高いクリーンアーキテクチャを避け、レイヤードアーキテクチャを採用。設計書がない中で、新機能には仕様書を残しつつ、既存コードの変換はAIに丸投げしてレビューで品質を担保するという、スピードと保守性のバランスを重視した移行プロセスが詳述されています。","importance":7},{"title":"GoogleやAppleなどのアカウント乗っ取りでPayPay不正利用の事例　サポートが注意喚起","url":"https://www.itmedia.co.jp/mobile/articles/2611/20/news069.html","source":"Hatena","published_at":"2026-11-20 22:10","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"GoogleやAppleアカウント乗っ取りによるPayPay不正利用への注意喚起","summary":"PayPay公式サポートが、Google、Apple、Yahoo!JAPANなどの外部連携アカウントの乗っ取りによるPayPay不正利用被害について注意喚起を行いました。これらのアカウントが不正アクセスされると、連携しているPayPayもログイン可能となり、不正利用されるリスクがあります。\n\n対策として、各サービスでの二段階認証の設定、パスワードの使い回し禁止、ログイン通知の確認が推奨されています。PayPay側では全額補償制度を設けていますが、外部連携アカウントのセキュリティ管理はユーザー自身の責任となるため、早急な対策が必要です。","importance":8},{"title":"MetaのAIエージェント「Muse」は何ができる？　ChatGPTやGeminiとの違い、注意点を解説","url":"https://www.itmedia.co.jp/mobile/articles/2611/22/news005.html","source":"Hatena","published_at":"2026-11-22 11:46","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"MetaのAIエージェント「Muse」：継続的な作業と自律的なタスク実行が可能な新ツール","summary":"Metaが日本で提供を開始したパーソナルAIエージェント「Muse」は、従来のチャットAIとは異なり、ユーザーごとにクラウド上の独立した仮想環境を持つ。これにより、作成したファイルや作業の途中経過が保持され、継続的なタスク実行や定期的な自動処理が可能となっている。\n\n「調べる」「作る」「続ける」というワークフローを軸に、メール要約やスケジュール管理、ダッシュボード作成などを自律的にこなす。他社のエージェント型サービスと比較して無料プランが充実している点が特徴。ブラウザやアプリから利用でき、定型作業をAIに任せたいユーザーにとって強力な選択肢となる。","importance":8},{"title":"Safari で contentEditable に focus() するとページ先頭へ飛ぶ問題の対処まとめ","url":"https://zenn.dev/qqpann/articles/safari-contenteditable-focus-scroll-jump","source":"Zenn","published_at":"2026-11-22 02:35","genre":"web","genre_label":"Web開発・言語","headline":"SafariでcontentEditableにfocus()するとページ先頭へ飛ぶ問題の対処法","summary":"Safariにおいて、contentEditable要素にfocus()した際にページが先頭へスクロールしてしまう現象の対処法を解説。原因はブラウザの自動スクロール機能によるものと推定される。\n\n解決策として、focus({ preventScroll: true }) を使用し、必要に応じて元のスクロール位置へ戻しつつ、対象要素を nearest で表示させる手法を提案。ただし、タッチ端末ではキーボード追従を阻害するため除外が必要となる。自動テストでの再現が困難な環境下での、目視確認による安全な修正アプローチをまとめた実践的な知見である。","importance":5},{"title":"相次ぐOSSの脆弱性に、とりあえずクラウドWAF入れるだけでだいぶ違う話+Rootlessコンテナもいいぞ","url":"https://zenn.dev/kusuke/articles/98e178e6824cac","source":"Zenn","published_at":"2026-11-19 10:34","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"OSS脆弱性ラッシュへの現実的な対策：クラウドWAF導入とRootlessコンテナ","summary":"PHPやnginxなど、Webサーバーや言語ランタイムの根幹に関わる脆弱性が相次ぐ中、パッチ適用までの時間を稼ぐための現実的な防衛策を提案しています。オリジンサーバーを直接さらさず、前段にL7クラウドWAFを配置することで、プロトコルレベルの攻撃を終端し、レート制限で悪用を阻止する手法です。\n\nCloudflare等の無料枠でも十分な効果があるとし、深夜の緊急パッチ対応に疲弊するエンジニアへの保険として推奨しています。あわせて、Rootlessコンテナの活用によるセキュリティ向上についても言及しています。","importance":9},{"title":"GitHub - awslabs/codekb","url":"https://github.com/awslabs/codekb","source":"Hatena","published_at":"2026-11-22 03:25","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"GitHub - awslabs/codekb：企業向けAIエージェントのためのコード理解プラットフォーム","summary":"「CodeKB」は、企業内の数百・数千に及ぶリポジトリを横断的に理解し、AIエージェントに文脈（コンテキスト）を提供するAWS Labsのプロジェクト。単なるコード検索ではなく、ビジネス概要やアーキテクチャ、技術スタックをMarkdownで生成し、エージェントがシステム全体を理解した上でタスクを実行できるようにする。\n\nMCPツールを通じてIDEやAIアシスタントと連携し、影響分析やデバッグ、リファクタリングを支援する。すべてのデータとモデルは自社のAWSアカウント内で完結するため、エンタープライズ環境での利用に適している。自律的なソフトウェア開発工場を実現するための基盤技術として注目される。","importance":8},{"title":"git ls-files -z の出力に trim() を掛けて、先頭が空白のファイルを検査から落としていた","url":"https://zenn.dev/nishi0001/articles/git-ls-files-z-trim-leading-space","source":"Zenn","published_at":"2026-11-21 22:49","genre":"web","genre_label":"Web開発・言語","headline":"git ls-filesの出力に対するtrim()が引き起こした検査漏れ","summary":"CIの検査スクリプトにおいて、ファイル名を取得する際にtrim()を適用していたことが原因で、空白で始まるファイル名が正しく処理されず検査から漏れる不具合が発生した。この修正を通じて、文字列加工の適切な適用範囲が再確認された。\n\n原因は、git ls-files -zの出力に対して無差別にtrim()を掛けていたことと、読み込み失敗を黙殺する例外処理が重なったことにある。修正後は、メールアドレスなど必要な箇所のみにtrim()を限定し、ファイル名には加工を施さない設計に変更。回帰テストとして特殊なファイル名を用いた検証を導入した。","importance":5},{"title":"ロボットとPLCのログ、3秒ずれると先に見える異常が変わる","url":"https://zenn.dev/nagi_lab/articles/0e86158fcdd169","source":"Zenn","published_at":"2026-11-22 00:03","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"ロボットとPLCのログ統合における時刻ずれの影響と補正手法","summary":"ロボットとPLCのログを統合する際、時刻同期が不完全だと異常発生の順序が入れ替わり、原因究明を誤るリスクがある。著者は合成データを用いて、3秒のずれが異常検知の前後関係を逆転させることを実証した。\n\n解決策として、共通のマーカー信号を用いた時刻補正手法を提案。複数のマーカーで差分を固定し、論理的に整合性が取れる場合にのみ補正を行うルールを設けている。実機環境ではスキャン周期や記録遅延も考慮する必要があるが、ログの目印選びが解析の精度を左右する重要な要素であることを示唆している。","importance":6},{"title":"ローカルLLMでクラウドのトークンを9割節約する","url":"https://zenn.dev/ace_toshi/articles/local-llm-confidential-mapreduce","source":"Zenn","published_at":"2026-11-22 00:45","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"ローカルLLMとMap-Reduceでクラウドのトークン消費を9割削減","summary":"議事録要約などの非本質的なタスクにクラウドLLMのトークンを消費することに疑問を感じた著者が、ローカルLLMを活用した要約システムを構築。長文を分割して処理するMap-Reduce手法を導入し、クラウドへの入力を87〜96%削減することに成功した。\n\n技術的な肝は、行の途中で分割しない厳格なチャンク制御と、文脈を「参照専用」として出力から排除する設計にある。この構成はトークン節約だけでなく、セキュリティポリシーにより外部APIへデータを送信できない環境での機密データ処理にもそのまま転用可能である。","importance":8},{"title":"AIが爆速で開発する時代の、自動テストとの向き合い方","url":"https://zenn.dev/daiaoki/articles/webterm-ai-era-testing","source":"Zenn","published_at":"2026-11-19 16:11","genre":"web","genre_label":"Web開発・言語","headline":"AI開発時代における自動テストの重要性とWebTerm Learnの品質管理","summary":"AIによる高速開発が進む中で、品質を維持するために自動テストをどのように育ててきたかの実践記録です。ブラウザ上で動作するLinuxシミュレーターをTypeScriptで実装し、副作用のない関数として設計することで、2.2万件もの単体テストを効率的に回す仕組みを構築しました。\n\nAIが書くコードの品質を担保するため、テストを「人の目で確かめる役割」として位置づけ、モノレポ化による依存関係の安定化を図っています。AI開発と自動テストを両立させるための具体的な設計指針が解説されています。","importance":7},{"title":"検証環境と外の環境を切り分けたいので VyOS を導入してみた。","url":"https://zenn.dev/y_mrok/articles/install_vyos","source":"Zenn","published_at":"2026-11-21 22:40","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"検証環境の分離を目的としたVyOSによるルーター構築","summary":"VMware Workstation Pro上にVyOSを導入し、検証環境を外部ネットワークから分離するためのルーターを構築した。LAN/WANインターフェースの設定、DHCP、DNSフォワーディング、NAT、ファイアウォールの設定手順を網羅している。\n\nVyOSのRolling Releaseを使用し、Debianベースの仮想マシンとしてセットアップ。WAN側からの新規通信を制限しつつ、LAN側からの通信を許可する構成を実現した。検証環境のネットワークを安全に管理するための実践的なガイドとなっており、ネットワークエンジニアにとって有用な構成例である。","importance":6},{"title":"RTX 4070 12GBでLLMを5モデル×520試行――再現性を監査してわかったこと","url":"https://zenn.dev/shinyahayakawa/articles/8d3892e901340a","source":"Zenn","published_at":"2026-11-21 21:11","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"RTX 4070でLLMの再現性を監査する実験プロトコル","summary":"ローカルLLMの実験において、モデルの動作確認だけでなく、結果の再現性と監査可能性を確保するための検証プロトコルを報告。RTX 4070環境で5モデル計2,600試行を実施し、実行条件の固定とログの整合性確認を行った。\n\nモデルのタグだけでなくdigestや実行コード、API呼び出しの順序までを固定・照合することで、後段の研究に耐えうる品質を担保。実行ハーネスの準備から実行可能性確認までの段階的なアプローチは、ローカルLLMを用いた学術的・技術的な実験において、再現性を維持するための重要な指針となる。","importance":8},{"title":"TypeScript 7.1 の Content Mapper で型の生成コマンドをなくす","url":"https://zenn.dev/toiroakr/articles/typescript-content-mapper-codegen","source":"Zenn","published_at":"2026-11-19 11:10","genre":"web","genre_label":"Web開発・言語","headline":"TypeScript 7.1のContent Mapperで型生成コマンドを不要にする手法","summary":"TypeScript 7.1で導入される「Content Mapper」を活用し、外部ファイルの型定義生成コマンドを廃止する手法の解説です。従来はPrismaやTanStack Routerのように、生成コマンドで型定義ファイルを埋め込む必要がありましたが、Content Mapperにより型チェック時に直接ファイルを変換して読み込めるようになります。\n\nこれにより、生成コマンドの実行忘れによる型不整合を防ぎ、開発体験を向上させることが可能です。ライブラリ開発者や大規模プロジェクトにおいて、型定義の管理を簡素化する強力な新機能です。","importance":7},{"title":"JVM がコードを実行する仕組みを理解したい","url":"https://zenn.dev/rea9r/articles/jvm-code-execution","source":"Zenn","published_at":"2026-11-21 17:06","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"JVMのJITコンパイルとコード実行の仕組みを徹底解説","summary":"JVMがバイトコードをどのように実行し、JITコンパイラがいつ何をコンパイルして保存するのかを解説。インタプリタからC1、C2コンパイラへの切り替えプロセスや、プロファイルに基づいた最適化、インライン化の仕組みを整理しています。\n\nまた、code cacheの役割や、JDKのバージョンアップに伴う内部挙動の変化についても言及。障害調査やパフォーマンスチューニングにおいて、JVMの内部構造を理解することがいかに重要であるかを、具体的な観測結果とともに示しています。","importance":7},{"title":"僕の Claude Code 開発のやり方（2026年11月）- AI に書かせて、別の AI に疑わせる","url":"https://zenn.dev/hironoah/articles/claude-code-my-workflow-202611","source":"Zenn","published_at":"2026-11-21 16:38","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIに書かせ、別のAIに疑わせるClaude Code開発フロー","summary":"Claude Codeを日常的に活用する開発者が、2026年11月時点での開発手法を公開。「書くのはAI、疑うのは別のAI、決めるのは自分」という原則のもと、実装とレビューを分離するフローを構築しています。\n\nメインのセッションには実装させず、サブエージェントに役割を分担させることでトークン消費を抑制。さらに、実装を知らない別のAIモデルに同時にレビューさせる「敵対的検証」を導入し、見落としを防ぐ仕組みを解説しています。失敗をルール化し、機械的に防ぐアプローチも特徴的です。","importance":9},{"title":"DOTweenを使わずにイージングを自作する！Robert Pennerのイージング関数をC#で実装して検証してみた","url":"https://zenn.dev/sorane/articles/e1ed930dea9b1d","source":"Zenn","published_at":"2026-11-21 01:03","genre":"web","genre_label":"Web開発・言語","headline":"DOTweenを使わずにイージング関数を自作・実装する方法","summary":"UnityやUnreal Engineのプロジェクトで、外部ライブラリを使わずにイージング関数を自作・実装する方法を解説。Robert Penner氏が考案した数式をベースに、0〜1の進行度を受け取って値を返す静的クラスとして実装する手法を紹介しています。\n\n31種類のイージングを列挙型で管理し、インスペクターから選択可能にする実装例を提示。補間処理をLerpに任せることで、float以外の値にも柔軟に対応できる設計にしています。既存のイージングの仕組みを理解し、プロジェクトの要件に合わせてカスタマイズするための実践的な技術記事です。","importance":5},{"title":"CDKからTerraformへ：所有権移譲による本番インフラ無停止のIaC移行","url":"https://zenn.dev/levtech/articles/14befd8e727f32","source":"Zenn","published_at":"2026-11-20 10:26","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"CDKからTerraformへ：本番インフラを停止させない所有権移譲によるIaC移行","summary":"AWS CDK v1のEOLに伴う技術的負債解消のため、本番環境を停止させずにTerraformへ移行した事例です。リソースを削除せずに「所有権を移譲する」手法を採用し、CloudFormationのスタックからリソースを切り離しつつTerraformへインポートすることで無停止移行を実現しました。\n\n段階的な移行手順や、AIを活用したコード生成、CIによる差分確認の工夫が詳細にまとめられています。IaCツールの統一を検討しているチームにとって、安全かつ確実な移行プロセスの参考となるナレッジです。","importance":8},{"title":"層化K分割交差検証とOOF予測：スコアを信頼できるものにする仕組み","url":"https://zenn.dev/py_ml_studio/articles/ad3484e227e368","source":"Zenn","published_at":"2026-11-22 09:03","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"機械学習の信頼性を高める「層化K分割交差検証」と「OOF予測」の仕組み","summary":"機械学習モデルの評価において、単一のデータ分割ではスコアが運に左右されるリスクがある。本記事では、全データを無駄なく評価し、モデルの実力を正確に見積もるための「層化K分割交差検証（Stratified K-Fold）」と「OOF（Out-Of-Fold）予測」の仕組みを解説する。\n\nクラス不均衡なデータセットにおいて、各foldのクラス割合を一定に保つ「層化」の重要性と、リーク（情報漏えい）を防ぐためのPipeline活用法を詳述。fitする処理を学習側のfold内だけで完結させる原則を守ることで、検証スコアの信頼性を担保し、本番環境での精度低下を防ぐための実践的な手法を学ぶことができる。","importance":7},{"title":"初心者がAIとMAXのAPKを解析してみた【後編】","url":"https://zenn.dev/aki0804/articles/ac6690df48a1ae","source":"Zenn","published_at":"2026-11-21 17:44","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Androidアプリ「MAX」のAPK解析と通信挙動の調査記録","summary":"Androidアプリ「MAX」のAPKを解析し、登録画面の通信や端末識別子、診断機能の挙動を調査した記録。Fridaを用いた関数フックとパケットキャプチャを組み合わせ、アプリの通信フローや暗号化された通信の解析手法を解説しています。\n\n特に、アプリのUIDに基づいた通信の特定や、TLS 1.3環境下でのセッション初期化要求の分析に焦点を当てています。AIエージェントの補助を活用し、エミュレーター環境での試験を通じて、アプリの内部挙動と通信の関連性を検証した技術的な調査レポートです。","importance":6},{"title":"ISUCONを Muse にやらせてみた：計測と実装を任せた8時間の記録｜バックエンドエンジニア・H執筆","url":"https://zenn.dev/oursship_blog/articles/ff9cdb2e04e781","source":"Zenn","published_at":"2026-11-22 02:19","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"ISUCONをAIエージェント「Muse」で攻略：計測・分析・実装を任せた8時間の記録","summary":"Webアプリの性能改善コンテスト「ISUCON」に、MetaのAIエージェント「Muse」を相棒として参加した記録。計測・分析・実装・デプロイをMuseに任せ、人間は方針決定とベンチマーク実行に集中する分担で挑んだ。\n\n自作ツール「isucon-kit」を用いてログ集計とボトルネック特定を行い、Museがコード修正を指示するフローを構築。結果としてスコアを大幅に伸ばすことに成功した。AIエージェントを活用することで、競技中の判断スピードと実装効率が向上することを示した。AIとエンジニアの協働による競技プログラミングの新しい可能性を提示している。","importance":7},{"title":"自宅サーバー上のアプリケーションを Cloudflare Tunnel + Access で安全に公開する","url":"https://zenn.dev/bisque/articles/home-server-cloudflare-tunnel-access","source":"Zenn","published_at":"2026-11-20 16:14","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Cloudflare TunnelとAccessで自宅サーバーを安全に公開する構成","summary":"個人開発アプリを安価な自宅サーバーで運用しつつ、セキュリティを確保するための構成として「Cloudflare Tunnel + Access」の活用法が紹介されています。ルーターのポートを開放せずに外部公開できるTunnelと、認証を前段で完結させるAccessを組み合わせることで、安全な環境を実現しています。\n\n認証機能をアプリ側に作り込む必要がなく、AIエージェントへのアクセス制御もサービストークンで管理可能です。Ansibleによる構成管理と合わせ、個人開発の運用効率と安全性を両立させる実践的なアーキテクチャです。","importance":7}]};
